UPDATE ICOMBYIT
   SET UNIT_MEASURE = #{UNIT_MEASURE}
     , CATEGORY_NO = #{CATEGORY_NO}
     , CATEGORY_TEXT = #{CATEGORY_TEXT}
     , CMS_CATLG_ID = #{CMS_CATLG_ID}
     , IMGFILE_NAME = #{IMGFILE_NAME}
     , IMGFILE_DIR = #{IMGFILE_DIR}
     , MAKER_CODE = #{MAKER_CODE}
     , MAKER_NAME = #{MAKER_NAME}
     , ORIGIN_CODE = #{ORIGIN_CODE}
     , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_USER_ID = #{st_user_id}
     , CHANGE_USER_NAME = #{st_user_name_loc}
 WHERE BUYER = #{BUYER}
   AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}

UPDATE ICOMCQDT
   SET UNIT_MEASURE = #{UNIT_MEASURE}
     , MAKER_CODE = #{MAKER_CODE}
     , MAKER_NAME = #{MAKER_NAME}
     , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE BUYER = #{BUYER}
   AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}

    UPDATE KEPQTDT 
       SET BUYER_ITEM_NO   = CASE WHEN BUYER_ITEM_NO LIKE 'NO_CODE%' THEN 'NO_CODE' ELSE BUYER_ITEM_NO END
	 WHERE BUYER = #{BUYER}
	   AND QUOTATION_NO = #{QUOTATION_NO}
	   AND QUOTATION_SEQ = #{QUOTATION_SEQ}
	   AND REVISION = #{REVISION}
       AND STATUS = 'C'

UPDATE ICOMBYIT SET BUYER_ITEM_NO = 'ksw'
 WHERE BUYER = #{BUYER}
   AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
   AND BUYER_ITEM_NO LIKE 'NO_CODE%'

